export type MentionedByArgs = { table: string; rowId: string; limit?: Count; offset?: Count };
export type MentionedByRow = { table: string; id: string; label: string };
export type MentionedByPage = { rows: MentionedByRow[]; nextOffset: Count | null; incomplete: boolean; indexing: boolean };
export type ViewEmbedArgs = { table: string; viewId: string; limit?: Count; calendar?: CalendarContext };
export type ViewEmbedColumn = { column: string; label: string; type: string };
export type CalendarPolicy = { timeZone?: string; dayStartMinutes: number };
/// Read-only preview rows projected to id plus the displayed columns. calendar asks the host to repeat the request with that policy's CalendarContext.
export type ViewEmbed = { name: string | null; columns: ViewEmbedColumn[]; rows: WorkspaceRow[]; more: boolean; calendar?: CalendarPolicy; unavailable?: string };
export type CatalogRevision = { revision: string };

export interface CoreOperations {
  catalog: { args: EmptyArgs; result: Catalog };
  /// Changes whenever any catalog row changes; compare before re-reading the whole catalog.
  catalogRevision: { args: EmptyArgs; result: CatalogRevision };
  /// columns is SQL projection and may omit id, updated_at and hidden fields; fetch a full row before editing. For visible layout only, omit columns when querying rows.
  rows: { args: View; result: WorkspaceRow[] };
  options: { args: OptionsArgs; result: string[] };
  write: { args: WriteArgs; result: Row };
  status: { args: EmptyArgs; result: SyncStatus };
  sync: { args: SyncArgs; result: SyncResult };
  serviceUsage: { args: EndpointArgs; result: UsageSummary };
  serviceNotifications: { args: EndpointArgs; result: NotificationFeed };
  markNotificationsRead: { args: NotificationReadArgs; result: NotificationReadResult };
  notificationPresentation: { args: NotificationPresentationArgs; result: NotificationPresentation };
  search: { args: SearchArgs; result: SearchHit[] };
  /// Builds and maintains the local search and backlink index in one bounded transaction: indexes rows changed since the last call, backfills newly indexed tables and removes tables that left it. Provenance and tables over the sync size rule are skipped unless `_core_state` key `search_tables` opts them in. Search and backlinks never build the index themselves.
  searchIndexStep: { args: SearchIndexStepArgs; result: SearchIndexStatus };
  /// Read-only: every table the search index can hold, whether it is indexed and why, its records and an estimate of its text, for a host's settings. Never builds or reconciles the index.
  searchTables: { args: EmptyArgs; result: SearchTableList };
  /// Stores this device's choice for one table in `_core_state` `search_tables` and returns the updated list. Hosts then schedule `searchIndexStep`, which backfills a table that joined the index and removes the entries of one that left it.
  setSearchTable: { args: SetSearchTableArgs; result: SearchTableList };
  /// columns is SQL projection and may omit id, updated_at and hidden fields; fetch a full row before editing. For visible layout only, omit columns when querying rows.
  listViews: { args: ListViewsArgs; result: SavedViewList };
  /// expectedUpdatedAt is required when id is supplied; omit both to create a new view.
  saveView: { args: SaveViewArgs; result: SavedViewRecord };
  deleteView: { args: DeleteViewArgs; result: SavedViewRecord };
  /// Read-only advisory. Always use write for the transactionally rechecked mutation.
  writeability: { args: WriteabilityArgs; result: Writeability };
  /// One bounded hub pull with no local row, checkpoint, coverage or outbox writes. A matching durable endpoint binding and local schema are required. Remote results are read-only.
  remoteRows: { args: RemoteRowsArgs; result: RemoteRowsPage };
  /// One bounded hub pull by ID; null means no matching row. Tombstones remain explicit. A matching durable endpoint binding and local schema are required.
  remoteRow: { args: RemoteRowArgs; result: RemoteRowResult };
  /// Read this handler instance's last saved change after queued session mutations settle. Closing the workspace discards the receipt. This is not a history query or a guarantee that undo will pass current validation.
  undoStatus: { args: EmptyArgs; result: UndoStatus };
  /// Undo last saved change through the ordinary validated writer, requiring the captured revision and shape. Success consumes the receipt; failure preserves it. No redo or timestamp restoration. Hosts pause autosave and preserve newer drafts for explicit review.
  undo: { args: UndoArgs; result: Row };
  /// Pure relative approval path and public fingerprint code. Hosts validate/canonicalize the endpoint and generate/hash the candidate token; core never receives it.
  enrollmentApproval: { args: EnrollmentApprovalArgs; result: EnrollmentApproval };
  /// Pure nonadmin identity validation and current full-scope replica eligibility. Dedicated manual names are allowed. No network or storage.
  validateDeviceSession: { args: SessionDataArgs; result: SessionInfo };
  /// Pure classification of one bounded session response, matching device:<fingerprint> only on approval. Hosts own deadline/cancellation and cap the returned retry delay to remaining time; never poll after the deadline.
  enrollmentPollResult: { args: EnrollmentPollArgs; result: EnrollmentPollResult };
  /// Pure classification of session POST. Only 200 with logged_out true confirms revocation; 401 is separately unauthorized, never proof that future approval is impossible.
  sessionRevocationResult: { args: SessionReply; result: SessionRevocationResult };
  /// Incoming live catalog ref/multi_ref definitions and persisted skipped-source warnings; no source row scans. Hosts load groups lazily.
  referenceSources: { args: ReferenceSourcesArgs; result: ReferenceSource[] };
  /// One bounded local incoming-reference group. Default 20 rows, maximum 100, live sources only. Target identity uses its primary-key collation, including trashed targets. Hosts ignore stale replies and re-read a row before opening it.
  referencedBy: { args: ReferencedByArgs; result: ReferencedByPage };
  /// Read the durable local rejection inbox without initialization or mutation. Missing storage is empty; malformed persisted data fails the whole page without skipping or deleting entries. An unchanged inbox has exact terminal detection, including a full final page.
  rejections: { args: RejectionsArgs; result: RejectionsPage };
  runRowAction: { args: RunRowActionArgs; result: Row };
  /// Resolve supported external source URLs through live whole-record imported_from provenance. Missing mappings remain external; ambiguous identities fail. Hosts re-resolve the destination before guarded navigation.
  resolveSourceLink: { args: SourceLinkArgs; result: SourceLinkResult };
  /// Calls only an explicitly injected, capability-validated governance adapter. Unconfigured handlers remain unavailable; no local writer fallback.
  historyEvents: { args: HistoryEventsArgs; result: HistoryEventsResult };
  /// Calls only an explicitly injected, capability-validated governance adapter. Unconfigured handlers remain unavailable; no local writer fallback.
  previewChanges: { args: PreviewRequest; result: PreviewResult };
  /// Calls only an explicitly injected, capability-validated governance adapter. Unconfigured handlers remain unavailable; no local writer fallback.
  createProposal: { args: CreateProposalArgs; result: ProposalMutationResult };
  /// Calls only an explicitly injected, capability-validated governance adapter. Unconfigured handlers remain unavailable; no local writer fallback.
  listProposals: { args: ListProposalsArgs; result: ProposalsResult };
  /// Calls only an explicitly injected, capability-validated governance adapter. Unconfigured handlers remain unavailable; no local writer fallback.
  getProposal: { args: GetProposalArgs; result: ProposalResult };
  /// Calls only an explicitly injected, capability-validated governance adapter. Unconfigured handlers remain unavailable; no local writer fallback.
  editProposal: { args: EditProposalArgs; result: ProposalMutationResult };
  /// Calls only an explicitly injected, capability-validated governance adapter. Unconfigured handlers remain unavailable; no local writer fallback.
  previewProposal: { args: PreviewProposalArgs; result: PreviewResult };
  /// Calls only an explicitly injected, capability-validated governance adapter. Unconfigured handlers remain unavailable; no local writer fallback.
  approveProposal: { args: ApproveProposalArgs; result: ApprovalResult };
  /// Calls only an explicitly injected, capability-validated governance adapter. Unconfigured handlers remain unavailable; no local writer fallback.
  rejectProposal: { args: RejectProposalArgs; result: ProposalMutationResult };
  /// Request hub-owned derivation for an unchanged saved row. Hosts retain drafts, then sync and re-read the record; this operation never writes replica values.
  resolveDerived: { args: ResolveDerivedArgs; result: ResolveDerivedResult };
  /// Lay out already loaded rows using host-supplied civil-day bounds. All-day end dates are inclusive; timed ends exclusive, with equal start/end treated as an instant. No query, write or timezone engine.
  calendarRows: { args: CalendarRowsArgs; result: CalendarRowsResult };
  /// Group already loaded rows by a select property, preserving supplied option order and unknown stored values. No writes.
  boardRows: { args: BoardRowsArgs; result: BoardRowsResult };
  pinTable: { args: PinTableArgs; result: SidebarPinList };
  listSidebarPins: { args: EmptyArgs; result: SidebarPinList };
  unpinTable: { args: UnpinTableArgs; result: SidebarPinList };
  moveTablePin: { args: MoveTablePinArgs; result: SidebarPinList };
  getViewDefault: { args: GetViewDefaultArgs; result: ViewDefault };
  /// Plain table navigation. Without an available preference, creates or restores the deterministic catalog-default saved view and points an absent or cleared preference at it; unavailable preferences keep their row and notice. No Undo receipt and no provisioning.
  ensureDefaultView: { args: GetViewDefaultArgs; result: ViewDefault };
  setViewDefault: { args: SetViewDefaultArgs; result: ViewDefault };
  /// Prepare a bounded read-only title-list or capped-count plan from the canonical compiler. No FTS, schema initialization, or query execution. Host owns stable workspace/replica identity, coherent publication, read-only work budget and exact guards in one read transaction.
  prepareReadPlan: { args: PrepareReadPlanArgs; result: ReadPlan };
  /// Explicit catalog mutation with the displayed revision; commits metadata and catalog_log together. Ordinary record writes remain read-only for catalog tables.
  saveCatalogProperty: { args: SaveCatalogPropertyArgs; result: Property };
  /// Explicit catalog mutation with the displayed revision; commits metadata and catalog_log together. Ordinary record writes remain read-only for catalog tables.
  saveCatalogRule: { args: SaveCatalogRuleArgs; result: Row };
  resolveViewDefinition: { args: ResolveViewDefinitionArgs; result: ResolvedViewDefinition };
  getRelatedViewDefault: { args: GetViewDefaultArgs; result: ViewDefault };
  setRelatedViewDefault: { args: SetViewDefaultArgs; result: ViewDefault };
  /// Checks the dump shape, format version, schema log and row counts without touching the replica.
  validateBackup: { args: BackupFileArgs; result: BackupSummary };
  previewRestore: { args: BackupFileArgs; result: RestorePreview };
  /// Writes the recovery dump, then replaces every ordinary table and the schema log in one transaction and resets device sync state.
  restoreReplica: { args: RestoreArgs; result: RestoreResult };
  /// Streams the portable SQL dump (the soma export shape) to a host destination.
  exportReplica: { args: BackupFileArgs; result: BackupSummary };
  hubBackups: { args: EndpointArgs; result: HubBackupList };
  createHubBackup: { args: EndpointArgs; result: HubBackup };
  /// Live display labels for iris://table/<table>/row/<id> mentions, at most 200 exact identities per request.
  mentionLabels: { args: MentionLabelsArgs; result: MentionLabel[] };
  /// Live records whose Markdown properties mention this exact record, from the local derived mentions index. Default 20, maximum 100, ordered by table and label.
  mentionedBy: { args: MentionedByArgs; result: MentionedByPage };
  /// A bounded read-only preview of one saved view for iris://table/<table>/view/<id> embeds. Default 10 rows, maximum 50.
  viewEmbed: { args: ViewEmbedArgs; result: ViewEmbed };
}
export type CoreMethod = keyof CoreOperations;
export type CoreArgs<M extends CoreMethod> = CoreOperations[M]["args"];
export type CoreResult<M extends CoreMethod> = CoreOperations[M]["result"];
export type CoreHandlers = { [M in CoreMethod]: (args: CoreArgs<M>) => CoreResult<M> | Promise<CoreResult<M>> };
